BEGIN;
CREATE TABLE public.school_classes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,name text NOT NULL,academic_year text NOT NULL,FOREIGN KEY(tenant_id,school_id) REFERENCES public.schools(tenant_id,id),UNIQUE(tenant_id,school_id,id),UNIQUE(tenant_id,school_id,name,academic_year));
CREATE TABLE public.class_student_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,class_id uuid NOT NULL,student_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('active','ended')),started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,FOREIGN KEY(tenant_id,school_id,class_id) REFERENCES public.school_classes(tenant_id,school_id,id),FOREIGN KEY(tenant_id,school_id,student_id) REFERENCES public.students(tenant_id,school_id,id),CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE UNIQUE INDEX class_student_one_active ON public.class_student_enrollments(tenant_id,school_id,class_id,student_id) WHERE status='active';
CREATE INDEX class_student_active_idx ON public.class_student_enrollments(tenant_id,school_id,student_id,class_id) WHERE status='active';
CREATE TABLE public.teacher_class_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,class_id uuid NOT NULL,teacher_user_id uuid NOT NULL REFERENCES public.users(id),status text NOT NULL CHECK(status IN ('active','ended')),FOREIGN KEY(tenant_id,school_id,class_id) REFERENCES public.school_classes(tenant_id,school_id,id));
CREATE UNIQUE INDEX teacher_class_one_active ON public.teacher_class_assignments(tenant_id,school_id,class_id,teacher_user_id) WHERE status='active';
CREATE TABLE public.guardian_student_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,school_id uuid NOT NULL,student_id uuid NOT NULL,guardian_user_id uuid NOT NULL REFERENCES public.users(id),relationship_code text NOT NULL,verification_status text NOT NULL CHECK(verification_status IN ('pending','verified','rejected','revoked')),verified_by uuid REFERENCES public.users(id),verified_at timestamptz,FOREIGN KEY(tenant_id,school_id,student_id) REFERENCES public.students(tenant_id,school_id,id),CHECK ((verification_status='verified' AND verified_by IS NOT NULL AND verified_at IS NOT NULL) OR verification_status<>'verified'));
CREATE UNIQUE INDEX guardian_verified_pair ON public.guardian_student_links(tenant_id,school_id,student_id,guardian_user_id) WHERE verification_status='verified';
CREATE INDEX guardian_verified_lookup ON public.guardian_student_links(guardian_user_id,tenant_id,school_id,student_id) WHERE verification_status='verified';
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['school_classes','class_student_enrollments','teacher_class_assignments','guardian_student_links'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION app.can_read_student_profile(p_tenant uuid,p_school uuid,p_student uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,app,public AS $$
SELECT app.current_user_id() IS NOT NULL AND EXISTS(SELECT 1 FROM public.students s WHERE s.id=p_student AND s.tenant_id=p_tenant AND s.school_id=p_school) AND
(app.has_active_membership(p_tenant,p_school,ARRAY['principal','school_admin'])
OR (app.has_active_membership(p_tenant,p_school,ARRAY['teacher']) AND EXISTS(SELECT 1 FROM public.teacher_class_assignments tca JOIN public.class_student_enrollments cse ON cse.tenant_id=tca.tenant_id AND cse.school_id=tca.school_id AND cse.class_id=tca.class_id WHERE tca.teacher_user_id=app.current_user_id() AND tca.tenant_id=p_tenant AND tca.school_id=p_school AND cse.student_id=p_student AND tca.status='active' AND cse.status='active'))
OR (app.has_active_membership(p_tenant,p_school,ARRAY['guardian']) AND EXISTS(SELECT 1 FROM public.guardian_student_links gsl WHERE gsl.guardian_user_id=app.current_user_id() AND gsl.tenant_id=p_tenant AND gsl.school_id=p_school AND gsl.student_id=p_student AND gsl.verification_status='verified'))
OR (app.has_active_membership(p_tenant,NULL,ARRAY['foundation_admin','foundation_analyst']) AND EXISTS(SELECT 1 FROM public.access_grants g JOIN public.access_requests r ON r.id=g.request_id WHERE g.grantee_user_id=app.current_user_id() AND g.tenant_id=p_tenant AND g.school_id=p_school AND g.student_id=p_student AND 'student_profile'=ANY(g.resource_types) AND r.status='approved' AND r.conflict_flag=false AND g.revoked_at IS NULL AND statement_timestamp()>=g.starts_at AND statement_timestamp()<g.expires_at AND g.approved_by<>g.grantee_user_id AND EXISTS(SELECT 1 FROM public.memberships pm WHERE pm.user_id=g.approved_by AND pm.tenant_id=p_tenant AND pm.school_id=p_school AND pm.status='active' AND pm.role_code='principal') AND NOT EXISTS(SELECT 1 FROM public.approval_escalations e WHERE e.request_id=g.request_id)))) $$;
CREATE POLICY g03c_student_profile_read ON public.students FOR SELECT USING(app.can_read_student_profile(tenant_id,school_id,id));
REVOKE ALL ON FUNCTION app.can_read_student_profile(uuid,uuid,uuid) FROM PUBLIC;
COMMIT;
